  /// Return the light's shader ID for the given list of available
  /// renderContexts (lightAPI.cpp:454-471).
  getShaderId(renderContexts: readonly string[]): string {
    // The passed in render contexts are in priority order so return the shader
    // ID from the first render context specific shaderId attribute that has a
    // a non-empty value.
    for (const renderContext of renderContexts) {
      const shaderIdAttr = this.getShaderIdAttrForRenderContext(renderContext)
      if (shaderIdAttr.isValid()) {
        const shaderId = shaderIdAttr.getValue()
        if (typeof shaderId === 'string' && shaderId !== '') {
          return shaderId
        }
      }
    }
    // Return the default shaderId attributes values if we couldn't get a value
    // for any of the render contexts.
    const shaderId = (this.getShaderIdAttr() as Attribute | undefined)?.getValue()
    return typeof shaderId === 'string' ? shaderId : ''
  }
