import {
  ConnectableAPI, ConnectableAPIBehavior, ConnectableNodeTypes, registerConnectableAPIBehavior,
  type BehaviorCanConnectResult, type BehaviorConnectionSource, type ShadeInput, type ShadeOutput,
} from 'typescript-usd/usdShade'
import { Type as TfType } from 'typescript-usd/tf'

// lightAPI.cpp:423-431.
function _GetShaderIdAttrName(renderContext: string): string {
  if (renderContext === '') {
    return UsdLuxTokens.lightShaderId
  }
  // SdfPath::JoinIdentifier(renderContext, lightShaderId).
  return `${renderContext}:${UsdLuxTokens.lightShaderId}`
}

// lightAPI.cpp:326-360: the behavior registered with
// TF_REGISTRY_FUNCTION(UsdShadeConnectableAPI).
class LightAPIConnectableAPIBehavior extends ConnectableAPIBehavior {
  // By default all UsdLuxLightAPI Connectable Behavior should be
  // container and not exhibit encapsulation behavior, as we expect lights to
  // be connected across multiple scopes, hence ignoring encapsulation rules.
  constructor() { super(true /*isContainer*/, false /*requiresEncapsulation*/) }
  override canConnectInputToSource(
    stage: Stage, inputPath: string, source: BehaviorConnectionSource,
  ): BehaviorCanConnectResult {
    return this._canConnectInputToSource(stage, inputPath, source,
      ConnectableNodeTypes.DerivedContainerNodes)
  }
  override canConnectOutputToSource(
    stage: Stage, outputPath: string, source: BehaviorConnectionSource,
  ): BehaviorCanConnectResult {
    return this._canConnectOutputToSource(stage, outputPath, source,
      ConnectableNodeTypes.DerivedContainerNodes)
  }
}
registerConnectableAPIBehavior(TfType.findByName('UsdLuxLightAPI'), new LightAPIConnectableAPIBehavior())
